const fs = require("node:fs");
const path = require("node:path");
const figlet = require("figlet");

const outputPath = path.resolve(__dirname, "../src/utils/banner.js");

figlet.text(
  "CatchTwo",
  {
    font: "Standard",
    horizontalLayout: "fitted",
    verticalLayout: "default",
  },
  (error, data) => {
    if (error) {
      console.error(error);
      process.exitCode = 1;
      return;
    }

    const content =
      "// Generated by npm run build:banner. Do not edit.\n" +
      "module.exports =\n" +
      `  ${JSON.stringify(data)};\n`;
    fs.writeFileSync(outputPath, content);
    console.log(
      `[build:banner] Wrote ${path.relative(process.cwd(), outputPath)}`
    );
  }
);
